  /**
   * @method
   * @name latoken#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://api.latoken.com/doc/v2/#tag/Trade/operation/getTradesByTrader
   * @see
   * https://api.latoken.com/doc/v2/#tag/Trade/operation/getTradesByAssetAndTrader
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // default 100
                 }
                 std::any response = ccxt::list{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("currency"),
                              ::getValue(market, std::string("baseId")));
                   ::setValue(request, std::string("quote"),
                              ::getValue(market, std::string("quoteId")));
                   response =
                       awaitValue(this->privateGetAuthTradePairCurrencyQuote(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privateGetAuthTrade(
                       this->extend(request, params)));
                 }
                 //
                 //     [
                 //         {
                 //             "id":"02e02533-b4bf-4ba9-9271-24e2108dfbf7",
                 //             "isMakerBuyer":false,
                 //             "direction":"TRADE_DIRECTION_BUY",
                 //             "baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f",
                 //             "quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5",
                 //             "price":"4564.32",
                 //             "quantity":"0.01000",
                 //             "cost":"45.6432",
                 //             "fee":"0.223651680000000000",
                 //             "order":"c9cac6a0-484c-4892-88e7-ad51b39f2ce1",
                 //             "timestamp":1635921580399,
                 //             "makerBuyer":false
                 //         }
                 //     ]
                 //
                 return this->parseTrades(response, market, since, limit);
               })
        .share();
  }

  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("ORDER_STATUS_PLACED"), std::string("open")},
        {std::string("ORDER_STATUS_CLOSED"), std::string("closed")},
        {std::string("ORDER_STATUS_CANCELLED"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

  virtual std::any parseOrderType(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("ORDER_TYPE_MARKET"), std::string("market")},
        {std::string("ORDER_TYPE_LIMIT"), std::string("limit")},
    };
    return this->safeString(statuses, status, status);
  }

  virtual std::any parseTimeInForce(std::any timeInForce) {
    std::any timeInForces = ccxt::dict{
        {std::string("ORDER_CONDITION_GOOD_TILL_CANCELLED"),
         std::string("GTC")},
        {std::string("ORDER_CONDITION_IMMEDIATE_OR_CANCEL"),
         std::string("IOC")},
        {std::string("ORDER_CONDITION_FILL_OR_KILL"), std::string("FOK")},
    };
    return this->safeString(timeInForces, timeInForce, timeInForce);
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    //
    // createOrder
    //
    //    {
    //        "baseCurrency": "f7dac554-8139-4ff6-841f-0e586a5984a0",
    //        "quoteCurrency": "a5a7a7a9-e2a3-43f9-8754-29a02f6b709b",
    //        "side": "BID",
    //        "clientOrderId": "my-wonderful-order-number-71566",
    //        "price": "10103.19",
    //        "stopPrice": "10103.19",
    //        "quantity": "3.21",
    //        "timestamp": 1568185507
    //    }
    //
    // fetchOrder, fetchOpenOrders, fetchOrders
    //
    //     {
    //         "id":"a76bd262-3560-4bfb-98ac-1cedd394f4fc",
    //         "status":"ORDER_STATUS_PLACED",
    //         "side":"ORDER_SIDE_BUY",
    //         "condition":"ORDER_CONDITION_GOOD_TILL_CANCELLED",
    //         "type":"ORDER_TYPE_LIMIT",
    //         "baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f",
    //         "quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5",
    //         "clientOrderId":"web-macos_chrome_1a6a6659-6f7c-4fac-be0b-d1d7ac06d",
    //         "price":"4000.00",
    //         "quantity":"0.01",
    //         "cost":"40.000000000000000000",
    //         "filled":"0",
    //         "trader":"7244bb3a-b6b2-446a-ac78-fa4bce5b59a9",
    //         "creator":"ORDER_CREATOR_USER",
    //         "creatorId":"",
    //         "timestamp":1635920767648
    //     }
    //
    // cancelOrder
    //
    //     {
    //         "message":"cancellation request successfully submitted",
    //         "status":"SUCCESS",
    //         "id":"a631426d-3543-45ba-941e-75f7825afb0f"
    //     }
    //
    std::any id = this->safeString(order, std::string("id"));
    std::any timestamp = this->safeInteger(order, std::string("timestamp"));
    std::any baseId = this->safeString(order, std::string("baseCurrency"));
    std::any quoteId = this->safeString(order, std::string("quoteCurrency"));
    std::any base = this->safeCurrencyCode(baseId);
    std::any quote = this->safeCurrencyCode(quoteId);
    std::any symbol = std::any{};
    if (isTrue(isTrue((!isEqual(base, std::any{}))) &&
               isTrue((!isEqual(quote, std::any{}))))) {
      symbol = add(add(base, std::string("/")), quote);
      if (isTrue(isTrue((!isEqual(this->markets, std::any{}))) &&
                 isTrue((inOp(this->markets, symbol))))) {
        market = this->market(symbol);
      }
    }
    std::any orderSide = this->safeString(order, std::string("side"));
    std::any side = std::any{};
    if (isTrue(!isEqual(orderSide, std::any{}))) {
      std::any parts = split(orderSide, std::string("_"));
      std::any partsLength = getArrayLength(parts);
      side = this->safeStringLower(parts, subtract(partsLength, 1));
    }
    std::any type =
        this->parseOrderType(this->safeString(order, std::string("type")));
    std::any price = this->safeString(order, std::string("price"));
    std::any amount = this->safeString(order, std::string("quantity"));
    std::any filled = this->safeString(order, std::string("filled"));
    std::any cost = this->safeString(order, std::string("cost"));
    std::any status =
        this->parseOrderStatus(this->safeString(order, std::string("status")));
    std::any message = this->safeString(order, std::string("message"));
    if (isTrue(!isEqual(message, std::any{}))) {
      if (isTrue(isGreaterThanOrEqual(
              getIndexOf(message, std::string("cancel")), 0))) {
        status = std::string("canceled");
      } else if (isTrue(isGreaterThanOrEqual(
                     getIndexOf(message, std::string("accept")), 0))) {
        status = std::string("open");
      }
    }
    std::any clientOrderId =
        this->safeString(order, std::string("clientOrderId"));
    std::any timeInForce = this->parseTimeInForce(
        this->safeString(order, std::string("condition")));
    return this->safeOrder(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("clientOrderId"), clientOrderId},
            {std::string("info"), order},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), std::any{}},
            {std::string("status"), status},
            {std::string("symbol"), symbol},
            {std::string("type"), type},
            {std::string("timeInForce"), timeInForce},
            {std::string("postOnly"), std::any{}},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("triggerPrice"),
             this->safeString(order, std::string("stopPrice"))},
            {std::string("cost"), cost},
            {std::string("amount"), amount},
            {std::string("filled"), filled},
            {std::string("average"), std::any{}},
            {std::string("remaining"), std::any{}},
            {std::string("fee"), std::any{}},
            {std::string("trades"), std::any{}},
        },
        market);
  }

  /**
   * @method
   * @name latoken#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see
   * https://api.latoken.com/doc/v2/#tag/Order/operation/getMyActiveOrdersByPair
   * @see
   * https://api.latoken.com/doc/v2/#tag/StopOrder/operation/getMyActiveStopOrdersByPair
   * // stop
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] true if fetching trigger orders
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{},
                  std::any limit = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchOpenOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any response = std::any{};
                 std::any isTrigger = this->safeValue2(
                     params, std::string("trigger"), std::string("stop"));
                 params = this->omit(params, std::string("stop"));
                 // privateGetAuthOrderActive doesn't work even though its
                 // listed at
                 // https://api.latoken.com/doc/v2/#tag/Order/operation/getMyActiveOrders
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(market, std::string("baseId"))},
                     {std::string("quote"),
                      ::getValue(market, std::string("quoteId"))},
                 };
                 if (isTrue(isEqual(isTrigger, true))) {
                   response = awaitValue(
                       this->privateGetAuthStopOrderPairCurrencyQuoteActive(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->privateGetAuthOrderPairCurrencyQuoteActive(
                           this->extend(request, params)));
                 }
                 //
                 //     [
                 //         {
                 //             "id":"a76bd262-3560-4bfb-98ac-1cedd394f4fc",
                 //             "status":"ORDER_STATUS_PLACED",
                 //             "side":"ORDER_SIDE_BUY",
                 //             "condition":"ORDER_CONDITION_GOOD_TILL_CANCELLED",
                 //             "type":"ORDER_TYPE_LIMIT",
                 //             "baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f",
                 //             "quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5",
                 //             "clientOrderId":"web-macos_chrome_1a6a6659-6f7c-4fac-be0b-d1d7ac06d",
                 //             "price":"4000.00",
                 //             "quantity":"0.01000",
                 //             "cost":"40.00",
                 //             "filled":"0.00000",
                 //             "trader":"7244bb3a-b6b2-446a-ac78-fa4bce5b59a9",
                 //             "creator":"USER",
                 //             "creatorId":"",
                 //             "timestamp":1635920767648
                 //         }
                 //     ]
                 //
                 return this->parseOrders(response, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name latoken#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see https://api.latoken.com/doc/v2/#tag/Order/operation/getMyOrders
   * @see https://api.latoken.com/doc/v2/#tag/Order/operation/getMyOrdersByPair
   * @see
   * https://api.latoken.com/doc/v2/#tag/StopOrder/operation/getMyStopOrders //
   * stop
   * @see
   * https://api.latoken.com/doc/v2/#tag/StopOrder/operation/getMyStopOrdersByPair
   * // stop
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] true if fetching trigger orders
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrders(std::any symbol = std::any{}, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any market = std::any{};
                 std::any isTrigger = this->safeValue2(
                     params, std::string("trigger"), std::string("stop"));
                 params =
                     this->omit(params, ccxt::list{std::string("stop"),
                                                   std::string("trigger")});
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // default 100
                 }
                 std::any response = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("currency"),
                              ::getValue(market, std::string("baseId")));
                   ::setValue(request, std::string("quote"),
                              ::getValue(market, std::string("quoteId")));
                   if (isTrue(isEqual(isTrigger, true))) {
                     response = awaitValue(
                         this->privateGetAuthStopOrderPairCurrencyQuote(
                             this->extend(request, params)));
                   } else {
                     response =
                         awaitValue(this->privateGetAuthOrderPairCurrencyQuote(
                             this->extend(request, params)));
                   }
                 } else {
                   if (isTrue(isEqual(isTrigger, true))) {
                     response = awaitValue(this->privateGetAuthStopOrder(
                         this->extend(request, params)));
                   } else {
                     response = awaitValue(this->privateGetAuthOrder(
                         this->extend(request, params)));
                   }
                 }
                 //
                 //     [
                 //         {
                 //             "id":"a76bd262-3560-4bfb-98ac-1cedd394f4fc",
                 //             "status":"ORDER_STATUS_PLACED",
                 //             "side":"ORDER_SIDE_BUY",
                 //             "condition":"ORDER_CONDITION_GOOD_TILL_CANCELLED",
                 //             "type":"ORDER_TYPE_LIMIT",
                 //             "baseCurrency":"620f2019-33c0-423b-8a9d-cde4d7f8ef7f",
                 //             "quoteCurrency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5",
                 //             "clientOrderId":"web-macos_chrome_1a6a6659-6f7c-4fac-be0b-d1d7ac06d",
                 //             "price":"4000.00",
                 //             "quantity":"0.01000",
                 //             "cost":"40.00",
                 //             "filled":"0.00000",
                 //             "trader":"7244bb3a-b6b2-446a-ac78-fa4bce5b59a9",
                 //             "creator":"USER",
                 //             "creatorId":"",
                 //             "timestamp":1635920767648
                 //         }
                 //     ]
                 //
                 return this->parseOrders(response, market, since, limit);
               })
        .share();
  }

